#!/usr/bin/env bash
# ============================================================================
# DailyLedger — Deploy Patch #5: FIX duplicate Loans/Borrowing content
#   (caused by patch_4 being re-run after the GitHub auth failure)
#
# ROOT CAUSE: patch_4's "already applied?" check tested whether the OLD
# anchor text was gone. But those edits were written as new = old + extra
# (appending content after an anchor), so the OLD text stayed present even
# after applying — the check never triggered, and the retry re-appended
# everything a second time. This produced:
#   - A duplicate "Loans / Borrowing" tab button
#   - A duplicate <div id="tab-loans"> panel
#   - A duplicate "loansDetailChart" canvas + a duplicate `new Chart(...)` call
#   - `const loanLabels` declared TWICE in the same <script> block — this is
#     a JavaScript SyntaxError, which silently killed the ENTIRE script on
#     that page: not just the Loans tab, but every tab and every chart
#     (Expense/Income/Payment/Savings included) stopped working.
#   - The same block of Python duplicated (harmless but wasteful) in views.py
#
# THIS SCRIPT: removes exactly the duplicated content, restoring each
# element to exactly one copy. Verified beforehand against an exact replica
# of the current (bugged) production files — before/after byte counts and a
# full functional re-test (correct totals, zero duplicate markers, page
# loads 200) all confirmed clean.
#
# Also fixes the underlying flaw: this script's own idempotency check tests
# for the OLD (broken, duplicated) text specifically — so it is safe to
# re-run, and unlike patch_4, a retry here cannot re-duplicate anything,
# because the fix is a pure removal, not an append.
#
# USAGE: paste this whole block directly into your SSH session.
# ============================================================================
set -euo pipefail

PROJECT_DIR="$HOME/dailyledger"
cd "$PROJECT_DIR"

echo "== 0. Pre-flight =="
if [ -d "venv" ]; then source venv/bin/activate; echo "Activated venv/"
elif [ -d ".venv" ]; then source .venv/bin/activate; echo "Activated .venv/"
else echo "WARNING: no venv/ found — using system python3."; fi

echo
echo "== 1. MANDATORY BACKUP (before touching anything) =="
DB_BACKUP_DIR="$PROJECT_DIR/backups/database"
PROJECT_BACKUP_DIR="$PROJECT_DIR/backups/project"

python manage.py run_backup --skip-notify

AFTER_DB_FILE=$(find "$DB_BACKUP_DIR" -name '*.sql.gz' -newermt '-2 minutes' 2>/dev/null | sort | tail -1)
AFTER_PROJ_FILE=$(find "$PROJECT_BACKUP_DIR" -name '*.tar.gz' -newermt '-2 minutes' 2>/dev/null | sort | tail -1)

if [ -z "$AFTER_DB_FILE" ] || [ ! -s "$AFTER_DB_FILE" ]; then
    echo "!! ABORT: no fresh, non-empty database backup file found — cannot verify backup succeeded."
    exit 1
fi
if [ -z "$AFTER_PROJ_FILE" ] || [ ! -s "$AFTER_PROJ_FILE" ]; then
    echo "!! ABORT: no fresh, non-empty project archive backup file found — cannot verify backup succeeded."
    exit 1
fi
echo "Backup verified:"
echo "  DB:      $AFTER_DB_FILE ($(du -h "$AFTER_DB_FILE" | cut -f1))"
echo "  Project: $AFTER_PROJ_FILE ($(du -h "$AFTER_PROJ_FILE" | cut -f1))"
echo "Safe to proceed."

echo
echo "== 2. Confirming the duplication is actually present (sanity check) =="
BTN_COUNT=$(grep -c 'id="tab-btn-loans"' templates/ledger/detail_reports.html || true)
PANEL_COUNT=$(grep -c 'id="tab-loans"' templates/ledger/detail_reports.html || true)
CHART_COUNT=$(grep -c "const loanLabels" templates/ledger/detail_reports.html || true)
echo "  tab-btn-loans occurrences: $BTN_COUNT (2 = bug present, 1 = already fixed)"
echo "  tab-loans occurrences: $PANEL_COUNT"
echo "  const loanLabels occurrences: $CHART_COUNT"
if [ "$BTN_COUNT" -le 1 ] && [ "$PANEL_COUNT" -le 1 ] && [ "$CHART_COUNT" -le 1 ]; then
    echo "  Nothing duplicated — already clean. Skipping straight to verification below."
    SKIP_PATCH=1
else
    SKIP_PATCH=0
fi

echo
echo "== 3. Git status before patch =="
git status --short

if [ "$SKIP_PATCH" -eq 0 ]; then
echo
echo "== 4. Removing the duplicated content =="
python3 - <<'PYEOF'
import base64, json, sys

MANIFEST_B64 = """
"""

manifest = json.loads(base64.b64decode(MANIFEST_B64).decode('utf-8'))

def patch(path, old, new, expect=1):
    with open(path, encoding='utf-8') as f:
        content = f.read()
    count = content.count(old)
    if count == 0:
        # old (the duplicated text) isn't there — already fixed, nothing to do.
        print(f"  [skip] {path}: duplication not found, already clean.")
        return
    if count != expect:
        print(f"  [FAIL] {path}: expected {expect} match(es) of the duplicated text, found {count}.")
        sys.exit(1)
    content = content.replace(old, new, 1)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(content)
    print(f"  [ok]   {path}: duplicate removed.")

for e in manifest['edits']:
    patch(e['path'], e['old'], e['new'])

print()
print("De-duplication complete.")
PYEOF
else
    echo "(skipped — nothing to patch)"
fi

echo
echo "== 5. Re-verify no duplication remains =="
BTN_COUNT=$(grep -c 'id="tab-btn-loans"' templates/ledger/detail_reports.html || true)
PANEL_COUNT=$(grep -c 'id="tab-loans"' templates/ledger/detail_reports.html || true)
CHART_COUNT=$(grep -c "const loanLabels" templates/ledger/detail_reports.html || true)
VIEWS_COUNT=$(grep -c "loans_taken_qs = Loan" ledger/views.py || true)
echo "  tab-btn-loans: $BTN_COUNT | tab-loans: $PANEL_COUNT | const loanLabels: $CHART_COUNT | views.py block: $VIEWS_COUNT"
if [ "$BTN_COUNT" -ne 1 ] || [ "$PANEL_COUNT" -ne 1 ] || [ "$CHART_COUNT" -ne 1 ] || [ "$VIEWS_COUNT" -ne 1 ]; then
    echo "!! Something is still off — expected exactly 1 of each. Stopping before commit."
    exit 1
fi
echo "  Confirmed: exactly one copy of everything."

echo
echo "== 6. Collect static =="
python manage.py collectstatic --noinput

echo
echo "== 7. Sanity check: Django can load the project =="
python manage.py check

echo
echo "== 8. Commit + push =="
git add -A
git status --short
git commit -m "Fix duplicate Loans/Borrowing tab content from patch_4 retry (removed JS SyntaxError that broke all report tabs)" --allow-empty
git push origin main

echo
echo "============================================================================"
echo "DONE. Duplication removed and verified (exactly 1 copy of each element)."
echo "Restart your app process now:"
echo "    sudo systemctl restart <your-gunicorn-service-name>"
echo "Then hard-refresh the Detail Reports page (Ctrl+Shift+R) and confirm:"
echo "  - Only ONE 'Loans / Borrowing' tab button"
echo "  - All tabs (Expense/Income/Payment/Savings/Loans) are clickable again"
echo "  - Charts render on every tab, not just Loans"
echo "Paste this script's full output back for verification."
echo "============================================================================"
